class StubLarkMediaAdapter:
    def __init__(self, payload: bytes = b'test-image-bytes'):
        self.payload = payload
        self.calls = []

    def download_image(self, message_id: str, file_key: str) -> bytes:
        self.calls.append((message_id, file_key))
        return self.payload


class StubLarkReplyAdapter:
    def __init__(self):
        self.calls = []

    def reply_text(self, *, message_id: str, text: str) -> dict:
        self.calls.append({'message_id': message_id, 'text': text})
        return {'ok': True}


class StubOcrAdapter:
    def __init__(self, raw_text: str = ""):
        self.raw_text = raw_text
        self.calls = []

    def extract_text(self, image_ref: str) -> dict:
        self.calls.append(image_ref)
        return {"raw_text": self.raw_text, "engine": "stub_ocr"}


class StubCrmDropdownAdapter:
    def __init__(self, apps=None, depts=None, error=None):
        self.apps = apps or []
        self.depts = depts or []
        self.error = error

    def get_apps(self):
        if self.error:
            raise RuntimeError(self.error)
        return list(self.apps)

    def get_depts(self):
        if self.error:
            raise RuntimeError(self.error)
        return list(self.depts)


class SyncingCrmDeptAdapter(StubCrmDropdownAdapter):
    def __init__(self, apps=None, depts=None, error=None):
        super().__init__(apps=apps, depts=depts, error=error)
        self.created_depts = []

    def create_dept(self, *, name, pid=0, sort=0):
        self.created_depts.append({'name': name, 'pid': pid, 'sort': sort})
        next_id = str(1000 + len(self.depts) + len(self.created_depts))
        self.depts.append({'id': next_id, 'name': name, 'deptName': name, 'pid': pid, 'sort': sort})
        return {'code': 0, 'msg': 'success', 'data': None}


def make_client(settings=None):
    cfg = {"DB_PATH": ":memory:", "AUTO_LARK_REPLY": False}
    if settings:
        cfg.update(settings)
    app = create_app(cfg)
    return TestClient(app)


def bootstrap_admin_and_login(client, *, username='admin01', password='secret123', display_name='Admin'):
    response = client.post('/api/ops/auth/bootstrap', json={
        'username': username,
        'password': password,
        'display_name': display_name,
    })
    assert response.status_code == 200
    return response.json()['user']


def test_approval_batch_summary_uses_daemon_snapshot_without_slow_fallback(monkeypatch):
    client = make_client({'AUTH_ENABLED': True})
    bootstrap_admin_and_login(client)
    service = client.app.state.service

    monkeypatch.setattr(service, 'list_whatsapp_approval_accounts', lambda *args, **kwargs: {
        'rows': [{
            'account_key': 'wa01',
            'enabled': True,
            'responsible_type': 'registration_group',
            'group_link_bindings': [{
                'enabled': True,
                'group_name': 'Carote-01',
                'registration_group': 'Carote-01',
            }],
        }],
    })
    monkeypatch.setattr(service, '_production_ops_daemon_snapshot', lambda: {
        'runtime': {'status': {'checked_at': '2026-05-20T12:00:00+00:00', 'registration_group_cycles': []}},
    })

    def slow_fallback_should_not_run():
        raise AssertionError('approval_batch_queue fallback should not run when daemon snapshot is fresh')

    monkeypatch.setattr(service, 'approval_batch_queue', slow_fallback_should_not_run)

    response = client.get('/api/ops/approval-batch-queue/summary')

    assert response.status_code == 200
    body = response.json()
    assert body['registration_groups'] == []
    assert body['registration_summary']['monitored_group_count'] == 0
    assert body['registration_summary']['pending_count'] == 0


