def test_production_ops_daemon_status_ignores_stale_incidents_when_no_approval_accounts(tmp_path, monkeypatch):
    status_path = tmp_path / 'production_ops_daemon_status.json'
    state_path = tmp_path / 'production_ops_daemon_state.json'
    status_path.write_text(json.dumps({
        'checked_at': '2026-05-14T08:14:44.368298+00:00',
        'incidents': [{
            'severity': 'critical',
            'code': 'worker_state_failed',
            'summary': '群状态探测失败',
        }],
        'observation_warnings': [],
        'notifications': [],
        'worker_state': {'ok': False, 'error': 'HTTP Error 500: Internal Server Error'},
        'registration_group_cycles': [{
            'group_id': '120363422719530134@g.us',
            'registration_group': '旧注册群',
            'pending_count': 8,
        }],
        'official_group_cycles': [],
    }, ensure_ascii=False), encoding='utf-8')
    state_path.write_text('{}', encoding='utf-8')
    monkeypatch.setattr(main_module, 'PRODUCTION_OPS_DAEMON_STATUS_PATH', status_path)
    monkeypatch.setattr(main_module, 'PRODUCTION_OPS_DAEMON_STATE_PATH', state_path)

    client = make_client()
    response = client.get('/api/ops/production-ops-daemon')

    assert response.status_code == 200
    status = response.json()['runtime']['status']
    assert status['checked_at'] == '2026-05-14T08:14:44.368298+00:00'
    assert status['incidents'] == []
    assert status['observation_warnings'] == []
    assert status['notifications'] == []
    assert status['registration_group_cycles'] == []
    assert status['official_group_cycles'] == []
    assert status['worker_state']['ok'] is True
    assert status['worker_state']['status'] == 'disabled_no_monitored_groups'


def test_whatsapp_approval_accounts_are_visible_only_to_assigned_customer_service():
    client = make_client({'AUTH_ENABLED': True})
    bootstrap_admin_and_login(client)

    cs1 = client.post('/api/ops/accounts', json={
        'username': 'cswa01',
        'password': 'operator123',
        'display_name': '客服 A',
        'role': 'customer_service',
        'enabled': True,
    }).json()['user']
    cs2 = client.post('/api/ops/accounts', json={
        'username': 'cswa02',
        'password': 'operator123',
        'display_name': '客服 B',
        'role': 'customer_service',
        'enabled': True,
    }).json()['user']

    def payload(assigned_user_id, group_suffix):
        return {
            'account_name': f'WA {group_suffix}',
            'responsible_type': 'registration_group',
            'assigned_customer_service_user_id': assigned_user_id,
            'group_link_bindings': [{
                'link': f'https://chat.whatsapp.com/{group_suffix}',
                'group_name': f'注册群 {group_suffix}',
                'area': 'Indonesia',
                'notify_profile_name': 'wa-approval-broadcast',
                'enabled': True,
                'approval_count_threshold': 30,
                'approval_timeout_minutes': 30,
                'auto_recover_worker': True,
                'schedule_windows': [{'start': '00:00', 'end': '23:59'}],
            }],
            'notify_profile_name': 'wa-approval-broadcast',
            'enabled': True,
        }

    a1 = client.post('/api/ops/whatsapp-approval-accounts/wa-assigned-a', json=payload(cs1['user_id'], 'assigned-a'))
    assert a1.status_code == 200
    assert a1.json()['account']['assigned_customer_service_user_id'] == cs1['user_id']
    assert a1.json()['account']['assigned_customer_service_display_name'] == '客服 A'
    a2 = client.post('/api/ops/whatsapp-approval-accounts/wa-assigned-b', json=payload(cs2['user_id'], 'assigned-b'))
    assert a2.status_code == 200

    all_rows = client.get('/api/ops/whatsapp-approval-accounts').json()['rows']
    assert {row['account_key'] for row in all_rows} == {'wa-assigned-a', 'wa-assigned-b'}
    assert len(client.get('/api/ops/whatsapp-approval-accounts').json()['customer_service_options']) == 2

    client.post('/api/ops/auth/logout')
    assert client.post('/api/ops/auth/login', json={'username': 'cswa01', 'password': 'operator123'}).status_code == 200
    cs1_rows = client.get('/api/ops/whatsapp-approval-accounts').json()['rows']
    assert [row['account_key'] for row in cs1_rows] == ['wa-assigned-a']
    cs1_overview_rows = client.get('/api/ops/whatsapp-approval-accounts/overview').json()['rows']
    assert [row['account_key'] for row in cs1_overview_rows] == ['wa-assigned-a']
    assert client.get('/api/ops/whatsapp-approval-accounts/wa-assigned-a/session').status_code == 200
    blocked = client.get('/api/ops/whatsapp-approval-accounts/wa-assigned-b/session')
    assert blocked.status_code == 403
    assert blocked.json()['detail'] == 'whatsapp_approval_account_not_assigned'
    blocked_update = client.post('/api/ops/whatsapp-approval-accounts/wa-assigned-b', json=payload(cs2['user_id'], 'assigned-b'))
    assert blocked_update.status_code == 403
    assert blocked_update.json()['detail'] == 'whatsapp_approval_account_not_assigned'

    client.post('/api/ops/auth/logout')
    assert client.post('/api/ops/auth/login', json={'username': 'cswa02', 'password': 'operator123'}).status_code == 200
    cs2_rows = client.get('/api/ops/whatsapp-approval-accounts').json()['rows']
    assert [row['account_key'] for row in cs2_rows] == ['wa-assigned-b']


def test_whatsapp_approval_account_save_requires_explicit_customer_service_assignment():
    client = make_client({'AUTH_ENABLED': True})
    bootstrap_admin_and_login(client)
    kefu = client.post('/api/ops/accounts', json={
        'username': 'kefu0001',
        'password': 'operator123',
        'display_name': 'kefu0001',
        'role': 'customer_service',
        'enabled': True,
    }).json()['user']

    payload = {
        'account_name': 'WA Explicit Kefu',
        'responsible_type': 'registration_group',
        'group_link_bindings': [{
            'link': 'https://chat.whatsapp.com/default-kefu',
            'group_name': '默认客服测试群',
            'area': 'Indonesia',
            'notify_profile_name': 'wa-approval-broadcast',
            'enabled': True,
            'approval_count_threshold': 30,
            'approval_timeout_minutes': 30,
            'auto_recover_worker': True,
            'schedule_windows': [{'start': '00:00', 'end': '23:59'}],
        }],
        'enabled': True,
    }

    missing = client.post('/api/ops/whatsapp-approval-accounts/wa-explicit-kefu', json=payload)
    assert missing.status_code == 400
    assert missing.json()['detail'] == 'assigned_customer_service_required'

    saved = client.post('/api/ops/whatsapp-approval-accounts/wa-explicit-kefu', json={
        **payload,
        'assigned_customer_service_user_id': kefu['user_id'],
    })
    assert saved.status_code == 200
    account = saved.json()['account']
    assert account['assigned_customer_service_user_id'] == kefu['user_id']
    assert account['assigned_customer_service_username'] == 'kefu0001'
    assert account['assigned_customer_service_display_name'] == 'kefu0001'


def test_whatsapp_approval_accounts_list_order_is_stable_by_created_at_not_updated_at():
    client = make_client()
    service = client.app.state.service
    with service.db.connect() as conn:
        conn.execute(
            """
            INSERT INTO whatsapp_approval_accounts (
                account_key, account_name, responsible_type, group_links, enabled, verification_status, created_at, updated_at
            ) VALUES (?, ?, ?, '[]', 1, 'pending_verification', ?, ?)
            """,
            ('registration-a', 'WA A', 'registration_group', '2026-06-03T01:00:00+00:00', '2026-06-03T09:00:00+00:00'),
        )
        conn.execute(
            """
            INSERT INTO whatsapp_approval_accounts (
                account_key, account_name, responsible_type, group_links, enabled, verification_status, created_at, updated_at
            ) VALUES (?, ?, ?, '[]', 1, 'pending_verification', ?, ?)
            """,
            ('registration-b', 'WA B', 'registration_group', '2026-06-03T02:00:00+00:00', '2026-06-03T03:00:00+00:00'),
        )
        conn.execute(
            """
            INSERT INTO whatsapp_approval_accounts (
                account_key, account_name, responsible_type, group_links, enabled, verification_status, created_at, updated_at
            ) VALUES (?, ?, ?, '[]', 1, 'pending_verification', ?, ?)
            """,
            ('official-z', 'WA Official', 'official_group', '2026-01-01T00:00:00+00:00', '2026-06-03T00:00:00+00:00'),
        )
        conn.commit()

    rows = service.list_whatsapp_approval_accounts(lightweight=True)['rows']
    assert [row['account_key'] for row in rows] == ['registration-a', 'registration-b', 'official-z']

    with service.db.connect() as conn:
        conn.execute(
            "UPDATE whatsapp_approval_accounts SET updated_at=? WHERE account_key=?",
            ('2026-06-03T12:00:00+00:00', 'registration-b'),
        )
        conn.commit()

    rows_after_update = service.list_whatsapp_approval_accounts(lightweight=True)['rows']
    assert [row['account_key'] for row in rows_after_update] == ['registration-a', 'registration-b', 'official-z']



def test_whatsapp_approval_accounts_backfill_created_at_and_preserve_it_on_save(tmp_path):
    import sqlite3

    db_path = tmp_path / 'approval-created-at.sqlite3'
    conn = sqlite3.connect(db_path)
    conn.execute(
        """
        CREATE TABLE whatsapp_approval_accounts (
            account_key TEXT PRIMARY KEY,
            account_name TEXT NOT NULL,
            responsible_type TEXT NOT NULL,
            group_links TEXT NOT NULL DEFAULT '[]',
            area TEXT,
            notify_profile_name TEXT,
            approval_rule TEXT NOT NULL DEFAULT 'count_30',
            approval_count_threshold INTEGER NOT NULL DEFAULT 30,
            approval_timeout_minutes INTEGER NOT NULL DEFAULT 30,
            auto_recover_worker INTEGER NOT NULL DEFAULT 1,
            schedule_windows TEXT NOT NULL DEFAULT '[]',
            enabled INTEGER NOT NULL DEFAULT 1,
            verification_status TEXT NOT NULL DEFAULT 'pending_verification',
            assigned_customer_service_user_id TEXT,
            assigned_customer_service_username TEXT,
            assigned_customer_service_display_name TEXT,
            notes TEXT,
            updated_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        """
        INSERT INTO whatsapp_approval_accounts (
            account_key, account_name, responsible_type, group_links, enabled, verification_status, updated_at
        ) VALUES (?, ?, ?, ?, 1, 'pending_verification', ?)
        """,
        (
            'legacy-registration',
            'Legacy Registration',
            'registration_group',
            json.dumps([
                {
                    'link': 'https://chat.whatsapp.com/legacy-a',
                    'group_name': 'Legacy 群',
                    'area': 'Indonesia',
                    'notify_profile_name': 'wa-approval-broadcast',
                    'enabled': True,
                    'approval_count_threshold': 30,
                    'approval_timeout_minutes': 30,
                    'auto_recover_worker': True,
                    'schedule_windows': [{'start': '00:00', 'end': '23:59'}],
                }
            ], ensure_ascii=False),
            '2026-06-03T04:28:37+00:00',
        ),
    )
    conn.commit()
    conn.close()

    app = create_app({'DB_PATH': str(db_path), 'AUTO_LARK_REPLY': False})
    client = TestClient(app)

    with app.state.service.db.connect() as check_conn:
        row = check_conn.execute(
            "SELECT created_at, updated_at FROM whatsapp_approval_accounts WHERE account_key=?",
            ('legacy-registration',),
        ).fetchone()
    assert row['created_at'] == '2026-06-03T04:28:37+00:00'
    assert row['updated_at'] == '2026-06-03T04:28:37+00:00'

    saved = client.post('/api/ops/whatsapp-approval-accounts/legacy-registration', json={
        'account_name': 'Legacy Registration Updated',
        'responsible_type': 'registration_group',
        'group_link_bindings': [{
            'link': 'https://chat.whatsapp.com/legacy-a',
            'group_name': 'Legacy 群',
            'area': 'Indonesia',
            'notify_profile_name': 'wa-approval-broadcast',
            'enabled': True,
            'approval_count_threshold': 35,
            'approval_timeout_minutes': 45,
            'auto_recover_worker': True,
            'schedule_windows': [{'start': '00:00', 'end': '23:59'}],
        }],
        'notify_profile_name': 'wa-approval-broadcast',
        'enabled': True,
    })
    assert saved.status_code == 200

    with app.state.service.db.connect() as check_conn:
        row_after_save = check_conn.execute(
            "SELECT created_at, updated_at FROM whatsapp_approval_accounts WHERE account_key=?",
            ('legacy-registration',),
        ).fetchone()
    assert row_after_save['created_at'] == '2026-06-03T04:28:37+00:00'
    assert row_after_save['updated_at'] != row_after_save['created_at']



def test_whatsapp_approval_binding_delete_reorder_preserves_binding_identity_and_live_names():
    client = make_client()
    account_key = 'wa-reorder-bindings'
    initial = client.post(f'/api/ops/whatsapp-approval-accounts/{account_key}', json={
        'account_name': 'WA Reorder',
        'responsible_type': 'registration_group',
        'group_link_bindings': [
            {
                'link': 'https://chat.whatsapp.com/group-38',
                'area': 'Indonesia',
                'notify_profile_name': 'wa-approval-broadcast',
                'enabled': True,
                'approval_count_threshold': 30,
                'approval_timeout_minutes': 30,
                'auto_recover_worker': True,
                'schedule_windows': [{'start': '00:00', 'end': '23:59'}],
            },
            {
                'link': 'https://chat.whatsapp.com/group-30',
                'area': 'Indonesia',
                'notify_profile_name': 'wa-approval-broadcast',
                'enabled': True,
                'approval_count_threshold': 30,
                'approval_timeout_minutes': 30,
                'auto_recover_worker': True,
                'schedule_windows': [{'start': '00:00', 'end': '23:59'}],
            },
            {
                'link': 'https://chat.whatsapp.com/group-31',
                'area': 'Indonesia',
                'notify_profile_name': 'wa-approval-broadcast',
                'enabled': True,
                'approval_count_threshold': 30,
                'approval_timeout_minutes': 30,
                'auto_recover_worker': True,
                'schedule_windows': [{'start': '00:00', 'end': '23:59'}],
            },
        ],
        'enabled': True,
    })
    assert initial.status_code == 200
    created_bindings = initial.json()['account']['group_link_bindings']
    assert len(created_bindings) == 3
    assert all(str(item.get('binding_id') or '').strip() for item in created_bindings)

    service = client.app.state.service
    seeded_bindings = []
    for binding, live_name, live_group_id in zip(
        created_bindings,
        ['38群', '30群', '31群'],
        ['12038@g.us', '12030@g.us', '12031@g.us'],
    ):
        seeded_bindings.append({
            **binding,
            'group_name': live_name,
            'registration_group': live_group_id,
            'group_id': live_group_id,
        })
    with service.db.connect() as conn:
        conn.execute(
            'UPDATE whatsapp_approval_accounts SET group_links=? WHERE account_key=?',
            (json.dumps(seeded_bindings, ensure_ascii=False), account_key),
        )
        conn.commit()

    reordered = client.post(f'/api/ops/whatsapp-approval-accounts/{account_key}', json={
        'account_name': 'WA Reorder',
        'responsible_type': 'registration_group',
        'group_link_bindings': [
            {
                'binding_id': seeded_bindings[1]['binding_id'],
                'link': seeded_bindings[1]['link'],
                'area': 'Indonesia',
                'notify_profile_name': 'wa-approval-broadcast',
                'enabled': True,
                'registration_group': '12030@g.us',
                'group_id': '12030@g.us',
                'approval_count_threshold': 30,
                'approval_timeout_minutes': 30,
                'auto_recover_worker': True,
                'schedule_windows': [{'start': '00:00', 'end': '23:59'}],
            },
            {
                'binding_id': seeded_bindings[2]['binding_id'],
                'link': seeded_bindings[2]['link'],
                'area': 'Indonesia',
                'notify_profile_name': 'wa-approval-broadcast',
                'enabled': True,
                'registration_group': '12031@g.us',
                'group_id': '12031@g.us',
                'approval_count_threshold': 30,
                'approval_timeout_minutes': 30,
                'auto_recover_worker': True,
                'schedule_windows': [{'start': '00:00', 'end': '23:59'}],
            },
        ],
        'enabled': True,
    })
    assert reordered.status_code == 200
    updated_bindings = reordered.json()['account']['group_link_bindings']
    assert [item['binding_id'] for item in updated_bindings] == [seeded_bindings[1]['binding_id'], seeded_bindings[2]['binding_id']]
    assert [item['group_name'] for item in updated_bindings] == ['30群', '31群']
    assert [item['link'] for item in updated_bindings] == [seeded_bindings[1]['link'], seeded_bindings[2]['link']]


