def test_intake_bot_presets_api_can_create_additional_bot_preset_and_resolve_by_app_id():
    client = make_client({'LARK_APP_ID': 'cli_test_app', 'LARK_DEFAULT_APP_NAME': 'Linky', 'LARK_DEFAULT_DEPT_NAME': 'Piso'})
