def test_lark_reply_templates_include_code_field_for_success_and_failures():
    client = make_client()
    service = client.app.state.service

    pending = service._format_lark_reply_text({
        'accepted': True,
        'next_action': 'queue_bind_check',
        'lead_status': 'bind_check_pending',
        'reply_phone': '+62 81234567890',
        'reply_id': '55667788',
        'reply_group': 'Piso-12',
        'reply_code': 'EKVFGQ',
    })
    assert pending.startswith('**⏳ Processing**')
    assert '**❌ Failed**' not in pending
    assert 'Code: EKVFGQ' in pending

    final_success = service._format_lark_reply_text({
        'accepted': True,
        'next_action': 'queue_group_join',
        'lead_status': 'bind_success',
        'crm_verified': True,
        'reply_phone': '81234567890',
        'reply_area_code': 62,
        'reply_id': '55667788',
        'reply_group': 'Piso-12',
        'reply_code': 'EKVFGQ',
    })
    assert final_success.startswith('**✅ Success**')
    assert 'Phone: +62 81234567890' in final_success
    assert 'Code: EKVFGQ' in final_success

    already_in_target_verified = service._format_lark_reply_text({
        'accepted': True,
        'next_action': 'queue_group_join',
        'lead_status': 'bind_success',
        'crm_verified': True,
        'bind_precheck': 'already_in_target_guild',
        'reply_phone': '+62 8989811289819',
        'reply_id': '46058697',
        'reply_group': '其他渠道',
        'reply_code': '-',
    })
    assert already_in_target_verified == (
        '**❌ Bind failed: Previously registered in this agency**\n'
        'Phone: +62 8989811289819\n'
        'ID: 46058697\n'
        'Group: 其他渠道\n'
        'Code: -'
    )
    assert service._classify_ops_intake_result_status({
        'accepted': True,
        'lead_status': 'bind_success',
        'crm_verified': True,
        'bind_precheck': 'already_in_target_guild',
        'reply_text': already_in_target_verified,
    }) == 'bind_failed'

    not_verified_yet = service._format_lark_reply_text({
        'accepted': True,
        'next_action': 'queue_group_join',
        'lead_status': 'bind_success',
        'crm_verified': False,
        'reply_phone': '81234567890',
        'reply_area_code': 62,
        'reply_id': '55667788',
        'reply_group': 'Piso-12',
        'reply_code': 'EKVFGQ',
    })
    assert not_verified_yet.startswith('**❌ Failed**')

    already_registered_crm_failed = service._format_lark_reply_text({
        'accepted': False,
        'reason': 'crm_sync_failed',
        'bind_precheck': 'already_in_target_guild',
        'result_reason': 'Data duplication.',
        'reply_phone': '+62 8989811289819',
        'reply_id': '46058697',
        'reply_group': '其他渠道',
        'reply_code': '-',
    })
    assert already_registered_crm_failed == (
        '**❌ Bind failed: Previously registered in this agency**\n'
        'Phone: +62 8989811289819\n'
        'ID: 46058697\n'
        'Group: 其他渠道\n'
        'Code: -'
    )
    assert service._classify_ops_intake_result_status({
        'accepted': False,
        'reason': 'already_in_target_guild',
        'result_code': 'already_in_target_guild',
        'bind_precheck': 'already_in_target_guild',
        'result_reason': 'Previously registered in this agency',
        'reply_text': already_registered_crm_failed,
    }) == 'bind_failed'

    bind_failed = service._format_lark_reply_text({
        'accepted': False,
        'reason': 'simulated_bind_failed',
        'result_reason': 'manual retry needed',
        'reply_phone': '+62 81234567890',
        'reply_id': '55667788',
        'reply_group': 'Piso-12',
        'reply_code': 'EKVFGQ',
    })
    assert 'Code: EKVFGQ' in bind_failed

    device_duplicate = service._format_lark_reply_text({
        'accepted': False,
        'reason': 'bind_check_failed',
        'result_reason': 'Perangkat ini telah mencapai batas maksimum guild yang dapat diikuti.',
        'reply_phone': '+62 81234567890',
        'reply_id': '55667788',
        'reply_group': 'Piso-12',
        'reply_code': 'EKVFGQ',
    })
    assert device_duplicate.startswith('**❌ Device Duplicate Registration**')
    assert 'Code: EKVFGQ' in device_duplicate

    bind_executor_unavailable = service._format_lark_reply_text({
        'accepted': False,
        'reason': 'bind_check_failed',
        'result_code': 'bind_executor_unavailable',
        'result_reason': 'Bind executor unavailable. Check backend runtime.',
        'reply_phone': '+62 81234567890',
        'reply_id': '55667788',
        'reply_group': 'Piso-12',
        'reply_code': 'EKVFGQ',
    })
