@pytest.mark.skip(reason='obsolete leads-aggregate approval queue test: server snapshot/runtime is authoritative')
def test_ops_approval_batch_queue_returns_ready_and_waiting_groups():
    client = make_client()
    client.app.state.service.runtime_health = lambda: {'registration_group_approval': {'configured': False}}
    for idx in range(30):
        client.post(
            "/api/leads/upsert",
            json={
                "trace_id": f"trace-batch-old-{idx}",
                "source_platform": "manual_cs",
                "source_page_id": "lark",
                "country": "Indonesia",
                "area_code": 62,
                "mobile": f"8999900{idx:04d}",
                "app_name": "Linky",
                "dept_name": "Piso",
                "pendaftaran_group": "Piso-30",
            },
        )
    lead = client.post(
        "/api/leads/upsert",
        json={
            "trace_id": "trace-batch-official-old",
            "source_platform": "manual_cs",
            "source_page_id": "lark",
            "country": "Indonesia",
            "area_code": 62,
            "mobile": "89999111111",
            "app_name": "Linky",
            "dept_name": "Piso",
            "pendaftaran_group": "Official-A",
        },
    ).json()
    submission = client.post(
        "/api/account-submissions",
        json={
            "lead_id": lead['lead_id'],
            "submission_type": "account_id",
            "account_id": "90909090",
            "account_id_type": "platform_uid",
            "source_channel": "manual_cs_lark",
            "submitted_by": "ops_batch_old",
            "submitted_at": "2026-04-15T11:00:00Z",
        },
    ).json()
    client.post(
        f"/api/tasks/{submission['task_id']}/bind-check-result",
        json={
            "status": "success",
            "result_code": "bind_ok",
            "result_reason": "bind success",
            "finished_at": "2026-04-15T11:01:00Z",
            "raw_result": {"guild_code": "Piso"},
        },
    )

    response = client.get('/api/ops/approval-batch-queue')
    assert response.status_code == 200
    body = response.json()
    registration = next(row for row in body['registration_groups'] if row['registration_group'] == 'Piso-30')
    assert registration['ready'] is True
    assert registration['pending_count'] == 30
    assert registration['reason_code'] == 'batch_size_reached'
    official = next(row for row in body['official_groups'] if row['registration_group'] == 'Official-A')
    assert official['pending_count'] == 1

    summary_response = client.get('/api/ops/approval-batch-queue/summary')
    assert summary_response.status_code == 200
    summary_body = summary_response.json()
    registration_summary = next(row for row in summary_body['registration_groups'] if row['registration_group'] == 'Piso-30')
    official_summary = next(row for row in summary_body['official_groups'] if row['registration_group'] == 'Official-A')
    assert registration_summary['pending_count'] == 30
    assert summary_body['registration_summary']['pending_count'] >= 30
    assert summary_body['registration_summary']['monitored_group_count'] >= 1
    assert 'ready' not in registration_summary
    assert 'release_count' not in registration_summary
    assert 'reason_code' not in registration_summary
    assert 'oldest_pending_at' not in registration_summary
    assert 'requesters' not in registration_summary
    assert official_summary['approval_scope'] == 'official_group'
    assert official_summary['pending_count'] == 1
    assert 'ready' not in official_summary
    assert 'release_count' not in official_summary
    assert 'requesters' not in official_summary



