    assert bind_metrics['recent_completed_count'] >= 1
    assert bind_metrics['avg_queue_wait_seconds'] == 5.0
    assert bind_metrics['avg_execution_seconds'] == 6.0
    assert bind_metrics['avg_end_to_end_seconds'] == 11.0
